import React, { useState } from 'react';
import styled from 'styled-components';
import { size } from '../device';
import { testimonials } from '../data/content';

const Section = styled.section`
  background-color: #1c1c1c;
  padding: 5rem 0;

  @media (max-width: ${size.mobile}) {
    padding: 3.5rem 0;
  }
`;

const Heading = styled.h2`
  font-family: 'Bitter', serif;
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  color: #faf8f5;
  text-align: center;
  margin: 0 0 3rem;
  padding: 0 2rem;

  em {
    font-style: italic;
  }
`;

const CarouselRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  padding: 0 1.5rem;

  @media (max-width: ${size.mobile}) {
    gap: 0.75rem;
    padding: 0 0.75rem;
  }
`;

const ArrowButton = styled.button`
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 50%;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  cursor: pointer;
  color: #faf8f5;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.2s, background-color 0.2s;

  &:hover {
    border-color: #7ecff4;
    background-color: rgba(126, 207, 244, 0.1);
    color: #7ecff4;
  }

  &:disabled {
    opacity: 0.25;
    cursor: default;
    &:hover {
      border-color: rgba(255, 255, 255, 0.25);
      background-color: transparent;
      color: #faf8f5;
    }
  }

  @media (max-width: ${size.mobile}) {
    width: 36px;
    height: 36px;
  }
`;

const Card = styled.div`
  max-width: 680px;
  width: 100%;
  text-align: center;
  padding: 0 0.5rem;
`;

const Quote = styled.p`
  font-family: 'Merriweather', serif;
  font-size: clamp(1rem, 2vw, 1.15rem);
  line-height: 1.8;
  color: #e8e4dc;
  margin: 0 0 1.75rem;
  font-style: italic;
`;

const Attribution = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
`;

const Name = styled.span`
  font-family: 'Bitter', serif;
  font-size: 1rem;
  font-weight: 700;
  color: #faf8f5;
`;

const Title = styled.span`
  font-family: 'Open Sans', sans-serif;
  font-size: 0.85rem;
  color: #7ecff4;
  font-style: italic;
`;

const Dots = styled.div`
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2.5rem;
`;

const Dot = styled.button`
  width: 6px;
  height: 6px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  padding: 0;
  background-color: ${({ active }) => (active ? '#7ecff4' : 'rgba(255,255,255,0.25)')};
  transition: background-color 0.2s;
`;

const renderSegments = (segments) =>
  segments.map((seg, i) => {
    if (seg.bold && seg.italic) return <strong key={i}><em>{seg.text}</em></strong>;
    if (seg.bold) return <strong key={i}>{seg.text}</strong>;
    if (seg.italic) return <em key={i}>{seg.text}</em>;
    return <span key={i}>{seg.text}</span>;
  });

const TestimonialsCarousel = () => {
  const [index, setIndex] = useState(0);

  const prev = () => setIndex(i => Math.max(0, i - 1));
  const next = () => setIndex(i => Math.min(testimonials.length - 1, i + 1));

  const t = testimonials[index];

  return (
    <Section id="testimonials">
      <Heading>
        Why I'm Supporting the <em>Spectator</em>
      </Heading>

      <CarouselRow>
        <ArrowButton onClick={prev} disabled={index === 0} aria-label="Previous">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6" />
          </svg>
        </ArrowButton>

        <Card>
          <Quote>{renderSegments(t.segments)}</Quote>
          <Attribution>
            <Name>—{t.name}</Name>
            <Title>{t.title}</Title>
          </Attribution>
        </Card>

        <ArrowButton onClick={next} disabled={index === testimonials.length - 1} aria-label="Next">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </ArrowButton>
      </CarouselRow>

      <Dots>
        {testimonials.map((_, i) => (
          <Dot key={i} active={i === index} onClick={() => setIndex(i)} aria-label={`Go to testimonial ${i + 1}`} />
        ))}
      </Dots>
    </Section>
  );
};

export default TestimonialsCarousel;
